/** Contravariant sink - can accept supertypes. */
final class TokenSink[-T] {
  private val received: mutable.ListBuffer[Any] = mutable.ListBuffer.empty

  def receive(item: T): Unit = received += item

  def drain(): List[Any] = {
    val result = received.toList
    received.clear()
    result
  }
}

/** Invariant handler - exact type matching required. */
final class BivariantHandler[T](private var value: T) {
  def get: T = value
  def set(newValue: T): Unit = { value = newValue }
  def transform(func: T => T): T = {
    value = func(value)
    value
  }
}

/** Abstract base tokenizer with generic input type. */
abstract class BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
    values.iterator.map(tokenize)
}

// ---------------------------------------------------------------------------
// String and Bytes handling
// ---------------------------------------------------------------------------

sealed trait StrOrBytes
object StrOrBytes {
  final case class Text(value: String) extends StrOrBytes
  final case class Bytes(value: Array[Byte]) extends StrOrBytes
}

/** Tokenizer for string and bytes types. */
final class StringTokenizer(
    val encoding: String = "utf-8",
    val normalizer: String => String = identity
) extends BaseTokenizer[StrOrBytes] {

  override def tokenize(value: StrOrBytes): Token = value match {
    case StrOrBytes.Text(text) =>
      Token(normalizer(text), TokenType.STRING)
    case StrOrBytes.Bytes(bytes) =>
      val decoded = new String(bytes, encoding)
      Token(normalizer(decoded), TokenType.STRING)
  }

  def tokenize(value: String): Token = tokenize(StrOrBytes.Text(value))
  def tokenize(value: Array[Byte]): Token = tokenize(StrOrBytes.Bytes(value))
}

// ---------------------------------------------------------------------------
// Numeric handling
// ---------------------------------------------------------------------------

sealed trait NumericValue { def originalType: String }
object NumericValue {
  final case class IntValue(value: Int) extends NumericValue { val originalType = "int" }
  final case class LongValue(value: Long) extends NumericValue { val originalType = "long" }
  final case class DoubleValue(value: Double) extends NumericValue { val originalType = "double" }
  final case class BigDecimalValue(value: BigDecimal) extends NumericValue { val originalType = "decimal" }
}

/** Tokenizer for numeric types with precision handling. */
final class NumericTokenizer(
    val precision: Int = 6,
    val formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[NumericValue] {

  override def tokenize(value: NumericValue): Token = {
    val (strValue, originalType) = value match {
      case NumericValue.BigDecimalValue(v) =>
        val scaled = v.setScale(precision, BigDecimal.RoundingMode.HALF_UP)
        (scaled.toString, v.getClass.getSimpleName)
      case NumericValue.DoubleValue(v) =>
        (String.format(s"%.${precision}f", Double.box(v)), "double")
      case NumericValue.IntValue(v) => (v.toString, "int")
      case NumericValue.LongValue(v) => (v.toString, "long")
    }
    Token(strValue, TokenType.NUMERIC, Map("original_type" -> originalType))
  }

  def tokenize(value: Int): Token = tokenize(NumericValue.IntValue(value))
  def tokenize(value: Long): Token = tokenize(NumericValue.LongValue(value))
  def tokenize(value: Double): Token = tokenize(NumericValue.DoubleValue(value))
  def tokenize(value: BigDecimal): Token = tokenize(NumericValue.BigDecimalValue(value))
}

// ---------------------------------------------------------------------------
// Temporal handling
// ---------------------------------------------------------------------------

/** Tokenizer for date/time types. */
final class TemporalTokenizer(formatStr: Option[String] = None)
    extends BaseTokenizer[Either[LocalDateTime, LocalDate]] {

  private val isoFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  override def tokenize(value: Either[LocalDateTime, LocalDate]): Token = {
    val fmt = formatStr
      .map(DateTimeFormatter.ofPattern)
      .getOrElse(value match {
        case Left(_) => isoFormatter
        case Right(_) => dateFormatter
      })

    val formatted = value match {
      case Left(dt) => dt.format(fmt)
      case Right(d) => d.format(fmt)
    }

    Token(formatted, TokenType.TEMPORAL)
  }

  def tokenize(value: LocalDateTime): Token = tokenize(Left(value))
  def tokenize(value: LocalDate): Token = tokenize(Right(value))
}

// ---------------------------------------------------------------------------
// Universal tokenizer
// ---------------------------------------------------------------------------

/** Tokenizer that handles multiple types with runtime dispatch. */
final class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: Any): Token = value match {
    case null => Token("NULL", TokenType.NULL)
    case tokenizable: Tokenizable => Token(tokenizable.toToken, TokenType.STRUCTURED)
    case s: String => stringTokenizer.tokenize(s)
    case b: Array[Byte] => stringTokenizer.tokenize(b)
    case i: Int => numericTokenizer.tokenize(i)
    case l: Long => numericTokenizer.tokenize(l)
    case d: Double => numericTokenizer.tokenize(d)
    case bd: BigDecimal => numericTokenizer.tokenize(bd)
    case dt: LocalDateTime => temporalTokenizer.tokenize(dt)
    case d: LocalDate => temporalTokenizer.tokenize(d)
    case other => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

// ---------------------------------------------------------------------------
// Complex Nested Generics
// ---------------------------------------------------------------------------

final class TokenRegistry[T] {
  private var registry: Map[String, TokenContainer[T]] = Map.empty
  private var handlers: Vector[T => Option[Token]] = Vector.empty

  def register(key: String, container: TokenContainer[T]): Unit =
    registry = registry.updated(key, container)

  def addHandler(handler: T => Option[Token]): Unit =
    handlers = handlers :+ handler

  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        container.getAll.toList.map { item =>
          handlers.iterator
            .map(_(item))
            .collectFirst { case Some(token) => token }
        }
    }
  }
}

// ---------------------------------------------------------------------------
// Higher-kinded type simulation
// ---------------------------------------------------------------------------

class TokenFunctor[T](val value: Option[T]) {
  def map[U](func: T => U): TokenFunctor[U] =
    new TokenFunctor(value.map(func))

  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] =
    value match {
      case Some(v) => func(v)
      case None => new TokenFunctor[U](None)
    }

  def getOrElse(default: => T): T = value.getOrElse(default)
}

object TokenFunctor {
  def apply[T](value: T): TokenFunctor[T] = new TokenFunctor(Option(value))
}

final class TokenMonad[T](value: Option[T]) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] = {
    val result = for {
      f <- funcWrapped.value
      v <- this.value
    } yield f(v)
    new TokenMonad(result)
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(Option(value))
}

// ---------------------------------------------------------------------------
// JSON Structure Tokenization
// ---------------------------------------------------------------------------

sealed trait JsonValue
object JsonValue {
  final case class JsString(value: String) extends JsonValue
  final case class JsNumber(value: BigDecimal) extends JsonValue
  final case class JsBoolean(value: Boolean) extends JsonValue
  case object JsNull extends JsonValue
  final case class JsArray(values: Vector[JsonValue]) extends JsonValue
  final case class JsObject(values: Map[String, JsonValue]) extends JsonValue

  private def escape(input: String): String =
    input.flatMap {
      case '"' => "\\\""
      case '\\' => "\\\\"
      case '\n' => "\\n"
      case '\r' => "\\r"
      case '\t' => "\\t"
      case c => c.toString
    }

  private def indent(level: Int): String = "  " * level

  def render(value: JsonValue, pretty: Boolean = false, level: Int = 0): String = value match {
    case JsString(v) => s"\"${escape(v)}\""
    case JsNumber(v) => v.toString()
    case JsBoolean(v) => v.toString
    case JsNull => "null"
    case JsArray(values) =>
      if (values.isEmpty) "[]"
      else if (!pretty) values.map(render(_, pretty, level)).mkString("[", ",", "]")
      else {
        val inner = values.map(v => indent(level + 1) + render(v, pretty, level + 1)).mkString(",\n")
        s"[\n$inner\n${indent(level)}]"
      }
    case JsObject(values) =>
      if (values.isEmpty) "{}"
      else if (!pretty) {
        values.map { case (k, v) => s"\"${escape(k)}\":${render(v, pretty, level)}" }
          .mkString("{", ",", "}")
      } else {
        val inner = values.map {
          case (k, v) => s"${indent(level + 1)}\"${escape(k)}\": ${render(v, pretty, level + 1)}"
        }.mkString(",\n")
        s"{\n$inner\n${indent(level)}}"
      }
  }
}

/** Tokenizer for JSON structures with recursive types. */
final class JsonTokenizer(val pretty: Boolean = false) {
  def tokenize(value: JsonValue): Token = {
    val jsonStr = JsonValue.render(value, pretty)
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList

    def descend(current: JsonValue, remaining: List[String]): Option[JsonValue] =
      remaining match {
        case Nil => Some(current)
        case head :: tail =>
          current match {
            case JsonValue.JsObject(values) => values.get(head).flatMap(descend(_, tail))
            case JsonValue.JsArray(values) if head.forall(_.isDigit) =>
              val idx = head.toInt
              if (idx >= 0 && idx < values.length) descend(values(idx), tail) else None
            case _ => None
          }
      }

    descend(value, parts).map(tokenize)
  }
}

// ---------------------------------------------------------------------------
// Whitespace Tokenizer - Basic Text Tokenization
// ---------------------------------------------------------------------------

final class WhitespaceTokenizer(
    val lowercase: Boolean = false,
    val minLength: Int = 0,
    val maxLength: Option[Int] = None,
    val stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) strip(word) else word
    val lowered = if (lowercase) stripped.toLowerCase else stripped

    if (lowered.length < minLength) None
    else {
      val limited = maxLength match {
        case Some(max) if lowered.length > max => lowered.take(max)
        case _ => lowered
      }
      Option(limited).filter(_.nonEmpty)
    }
  }

  private def strip(word: String): String = {
    word.dropWhile(punctuation.contains)
      .reverse.dropWhile(punctuation.contains)
      .reverse
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    val tokens = mutable.ListBuffer.empty[Token]

    words.zipWithIndex.foreach { case (word, i) =>
      processToken(word).foreach { processed =>
        tokens += Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }

    tokens.toList
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    words.foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length
      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }
      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

// ---------------------------------------------------------------------------
// Builder Pattern with Fluent Interface
// ---------------------------------------------------------------------------

final case class TokenizerBuilder[T](
    normalizers: Vector[String => String] = Vector.empty,
    validators: Vector[T => Boolean] = Vector.empty,
    metadata: Map[String, Any] = Map.empty
) {

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] =
    copy(normalizers = normalizers :+ normalizer)

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] =
    copy(validators = validators :+ validator)

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] =
    copy(metadata = metadata ++ entries.toMap)

  def build(): T => Token = {
    val capturedNormalizers = normalizers
    val capturedValidators = validators
    val capturedMetadata = metadata

    value: T => {
      capturedValidators.foreach { validator =>
        if (!validator(value)) throw new IllegalArgumentException(s"Validation failed for $value")
      }

      val normalized = capturedNormalizers.foldLeft(value.toString) { (acc, n) => n(acc) }
      Token(normalized, TokenType.STRING, capturedMetadata)
    }
  }
}

